package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CpioArchiveOutputStream.close()
 */
public class CpioArchiveOutputStream_close_TriageGen1Test {

    /**
     * Tests that calling close() when the stream is not yet closed 
     * executes the logic to call super.close() and sets the closed flag.
     */
    @Test
    public void testClose_FirstTime_Success() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos, CpioArchiveOutputStream.BUILD) ) {
            // Before close, we check if it's functional (implicitly testing state)
            cos.close();
            // If we reach here without exception, the branch was taken
        }
    }

    /**
     * Tests that calling close() multiple times does not trigger the logic again.
     * This tests the 'if (!this.closed)' branch (the false case).
     */
    @Test
    public void testClose_CalledTwice_DoesNotThrow() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos, CpioArchiveOutputStream.BUILD);

        cos.close(); // First call: closed becomes true

        // Second call: should enter the 'else' (effectively) because !this.closed is false
        cos.close(); 

        // If no exception is thrown, the branch coverage is achieved
    }

    /**
     * Tests the behavior when the underlying OutputStream throws an IOException during close.
     * This ensures the exception propagates correctly.
     */
    @Test(expected = IOException.class)
    public void testClose_UnderlyingStreamThrowsException() throws IOException {
        OutputStream errorStream = new OutputStream() {
            @Override
            public void close() throws IOException {
                throw new IOException("Simulated close failure");
            }

            @Override
            public void write(int b) throws IOException {
                // no-op
            }
        };

        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(errorStream, CpioArchiveOutputStream.BUILD);
        cos.close();
    }

    /**
     * Tests that calling close() after adding entries works as expected.
     */
    @Test
    public void testClose_AfterWritingData() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos, CpioArchiveOutputStream.BUILD);

        CpioArchiveEntry entry = new CpioArchiveEntry("test.txt");
        entry.setSize(4);
        cos.putArchiveEntry(entry);
        cos.write("test".getBytes());
        cos.closeArchiveEntry();

        cos.close();

        Assert.assertTrue("Stream should be closed", true);
    }
}
